    """Reverse the color order of nested rectangular layers within each object."""
    h, w = len(grid), len(grid[0])
    seen = set()
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            colors = {}
            for y, x in cells:
                colors.setdefault(grid[y][x], []).append((y, x))
            def bounds(points):
                return (min(y for y,x in points), max(y for y,x in points),
                        min(x for y,x in points), max(x for y,x in points))
            # Nested rectangular layers have strictly decreasing bounding-box area.
            order = sorted(colors, key=lambda k: (-(bounds(colors[k])[1]-bounds(colors[k])[0]+1) *
                                                   (bounds(colors[k])[3]-bounds(colors[k])[2]+1), k))
            mapping = {color: order[-1-i] for i, color in enumerate(order)}
            for y, x in cells:
                out[y][x] = mapping[grid[y][x]]
